import React, { useState, useEffect, useCallback } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import styled from "styled-components";

const EmployeePage = () => {
  const { id } = useParams();
  const [employeeName, setEmployeeName] = useState("");
  const [employeePhone, setEmployeePhone] = useState("");
  const [employeeRole, setEmployeeRole] = useState("driver");
  const [employeeSalary, setEmployeeSalary] = useState("");
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [isFormVisible, setFormVisible] = useState(false);
  const [isUpdateFormVisible, setUpdateFormVisible] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [salaryDetails, setSalaryDetails] = useState({
    startDate: "",
    endDate: "",
    expense: "",
    daysWorked: 0,
  });

  // Fetch employees by role
  const fetchEmployeesByRole = useCallback(async (role) => {
    try {
      const response = await axios.get(
        `http://localhost:5001/api/employee/employeesByRole/${id}/${role}`
      );
      setFilteredEmployees(response.data);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  }, [id]);

  // Handle adding a new employee
  const addEmployee = async () => {
    try {
      const newEmployee = {
        name: employeeName,
        phone: employeePhone,
        role: employeeRole,
        fixed_salary: employeeSalary,
        lorry_id: id,
      };
      await axios.post("http://localhost:5001/api/employee/add", newEmployee);
      alert("Employee added successfully");
      fetchEmployeesByRole(employeeRole);
      setFormVisible(false);
    } catch (error) {
      console.error("Error adding employee:", error);
      alert("Error adding employee");
    }
  };

  // Handle updating employee salary details
  const updateEmployee = async () => {
    if (!selectedEmployee) {
      alert("Please select an employee first");
      return;
    }

    try {
      const { startDate, endDate, expense, daysWorked } = salaryDetails;
      await axios.put(
        `http://localhost:5001/api/employee/updateSalary/${selectedEmployee.phone}`,
        {
          startDate,
          endDate,
          expense,
          daysWorked,
        }
      );
      alert("Salary details updated successfully");
      fetchEmployeesByRole(employeeRole);
      setUpdateFormVisible(false);
    } catch (error) {
      console.error("Error updating salary details:", error);
      alert("Error updating salary details");
    }
  };

  // Calculate days worked
  const handleDateChange = () => {
    const startDate = new Date(salaryDetails.startDate);
    const endDate = new Date(salaryDetails.endDate);
    const timeDiff = Math.abs(endDate - startDate);
    const daysWorked = Math.ceil(timeDiff / (1000 * 3600 * 24)) + 1;
    setSalaryDetails((prevDetails) => ({
      ...prevDetails,
      daysWorked,
    }));
  };

  // Fetch employees when role changes
  useEffect(() => {
    fetchEmployeesByRole(employeeRole);
  }, [employeeRole, id, fetchEmployeesByRole]);

  return (
    <Container>
      <Header>
        <LorryTitle>Lorry {id}</LorryTitle>
      </Header>

      <Button onClick={() => setFormVisible(true)}>Add Employee</Button>

      {isFormVisible && (
        <Form>
          <Input
            type="text"
            placeholder="Employee Name"
            value={employeeName}
            onChange={(e) => setEmployeeName(e.target.value)}
          />
          <Input
            type="text"
            placeholder="Phone Number"
            value={employeePhone}
            onChange={(e) => setEmployeePhone(e.target.value)}
          />
          <Select
            value={employeeRole}
            onChange={(e) => setEmployeeRole(e.target.value)}
          >
            <option value="driver">Driver</option>
            <option value="driller">Driller</option>
            <option value="manager">Manager</option>
            <option value="worker">Worker</option>
          </Select>
          <Input
            type="number"
            placeholder="Fixed Salary"
            value={employeeSalary}
            onChange={(e) => setEmployeeSalary(e.target.value)}
          />
          <Button onClick={addEmployee}>Add Employee</Button>
          <Button onClick={() => setFormVisible(false)}>Cancel</Button>
        </Form>
      )}

      {isUpdateFormVisible && selectedEmployee && (
        <Form>
          <Input
            type="text"
            value={selectedEmployee.phone}
            readOnly
            placeholder="Phone Number"
          />
          <Input
            type="date"
            placeholder="Start Date"
            value={salaryDetails.startDate}
            onChange={(e) => {
              setSalaryDetails({ ...salaryDetails, startDate: e.target.value });
              handleDateChange();
            }}
          />
          <Input
            type="date"
            placeholder="End Date"
            value={salaryDetails.endDate}
            onChange={(e) => {
              setSalaryDetails({ ...salaryDetails, endDate: e.target.value });
              handleDateChange();
            }}
          />
          <Input
            type="number"
            placeholder="Expense"
            value={salaryDetails.expense}
            onChange={(e) =>
              setSalaryDetails({ ...salaryDetails, expense: e.target.value })
            }
          />
          <Input
            type="number"
            value={salaryDetails.daysWorked}
            readOnly
            placeholder="Days Worked"
          />
          <Button onClick={updateEmployee}>Update Salary</Button>
          <Button onClick={() => setUpdateFormVisible(false)}>Cancel</Button>
        </Form>
      )}

      <Select
        value={employeeRole}
        onChange={(e) => setEmployeeRole(e.target.value)}
      >
        <option value="driver">Driver</option>
        <option value="driller">Driller</option>
        <option value="manager">Manager</option>
        <option value="worker">Worker</option>
      </Select>

      <EmployeeList>
        {filteredEmployees.map((employee) => (
          <EmployeeItem key={employee.phone}>
            {employee.name} - {employee.phone}
          </EmployeeItem>
        ))}
      </EmployeeList>
    </Container>
  );
};

export default EmployeePage;


// Styled Components
const Container = styled.div`
  padding: 20px;
  background-color: #f4f7fc;
`;

const Header = styled.header`
  display: flex;
  justify-content: center;
  padding: 20px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const LorryTitle = styled.h1`
  font-size: 2rem;
  font-weight: bold;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: #4caf50;
  color: white;
  font-size: 1.1rem;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  margin-top: 20px;

  &:hover {
    background-color: #45a049;
  }
`;

const Form = styled.div`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const Select = styled.select`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const EmployeeRoles = styled.div`
  margin-top: 30px;
`;

const RoleTabs = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
`;

const Tab = styled.div`
  padding: 10px 20px;
  margin: 0 10px;
  cursor: pointer;
  background-color: #f0f0f0;
  border-radius: 5px;
  font-weight: bold;

  &:hover {
    background-color: #ddd;
  }
`;

const EmployeeList = styled.ul`
  list-style-type: none;
  padding: 0;
`;

const EmployeeItem = styled.li`
  font-size: 1rem;
  padding: 5px;
  border-bottom: 1px solid #ccc;
  cursor: pointer;

  &:hover {
    background-color: #f4f4f9;
  }
`;

const EmployeeDetails = styled.div`
  background-color: #fff;
  padding: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  margin-top: 20px;
`;

const DetailsTable = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;

  th,
  td {
    border: 1px solid #ddd;
    padding: 8px;
    text-align: left;
  }

  th {
    background-color: #f4f4f4;
    font-weight: bold;
  }
`;

const CardGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 20px;
`;
